@EventBusSubscriber(modid="around_planet",value=Dist.CLIENT)
public final class OrbitalHelmetHud {
    private static long uploadTick=Long.MIN_VALUE;public static long geometryBatches,textureUploads;
    private static DynamicTexture texture;private static ResourceLocation id;private static SpaceVector cachedUp;private static net.minecraft.client.multiplayer.ClientLevel level;
    public static long frames,plannerFrames,statsFrames,targetMarkers;public static int visibleTargetMarkers,cardinalLabels;public static NavballLayout lastLayout;
    private record Bindings(OrbitalSensorBlockEntity sensor,io.github.astelev.around_planet.maneuver.ManeuverPlannerBlockEntity planner,ItemStack helmet){}
    private record Row(Component text,int color){}
    private record Label(int x,int y,String text,int color,int priority){}
    private static Bindings bindings(){var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||!net.neoforged.fml.ModList.get().isLoaded("aeroengineering"))return null;var helmet=mc.player.getItemBySlot(EquipmentSlot.HEAD);if(!net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(helmet.getItem()).equals(ResourceLocation.fromNamespaceAndPath("aeroengineering","engine_monitor_helmet")))return null;
        OrbitalSensorBlockEntity sensor=null;io.github.astelev.around_planet.maneuver.ManeuverPlannerBlockEntity planner=null;for(var pos:AeroHelmetBridge.targets(helmet)){if(!mc.level.hasChunkAt(pos)||!AeroHelmetBridge.enabled(helmet,pos))continue;var be=mc.level.getBlockEntity(pos);if(be==null||!Objects.equals(AeroHelmetBridge.structure(helmet),io.github.astelev.around_planet.compat.SableSensorVisual.structure(be)))continue;if(be instanceof OrbitalSensorBlockEntity found&&sensor==null)sensor=found;else if(be instanceof io.github.astelev.around_planet.maneuver.ManeuverPlannerBlockEntity found&&planner==null)planner=found;}return sensor==null&&planner==null?null:new Bindings(sensor,planner,helmet);
    }
    public static boolean handlesTelemetry(){return bindings()!=null;}
    @SubscribeEvent public static void render(net.neoforged.neoforge.client.event.RenderGuiEvent.Post event){var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.options.hideGui||mc.screen!=null)return;var linked=bindings();if(linked==null)return;var sensor=linked.sensor();var planner=linked.planner();var telemetry=SpaceHud.current();var rows=new ArrayList<Row>();
        if(planner!=null){plannerFrames++;long now=mc.level.getGameTime();boolean next=planner.nextTick()>=now;rows.add(new Row(next?Component.translatable("around_planet.maneuver.countdown",String.format(Locale.ROOT,"%.1f",(planner.nextTick()-now)/20.0)):Component.translatable("around_planet.maneuver.none"),planner.getBlockState().getValue(io.github.astelev.around_planet.maneuver.ManeuverPlannerBlock.POWERED)?0xffffb24f:0xffa7dbe7));rows.add(new Row(Component.literal(next?String.format(Locale.ROOT,"Δv %.2f m/s",planner.deltaV()):"Δv —"),0xffffd180));}
        SpaceState state=null;if(telemetry!=null&&telemetry.active()){state=new SpaceState(new SpaceVector(telemetry.x(),telemetry.y(),telemetry.z()),new SpaceVector(telemetry.vx(),telemetry.vy(),telemetry.vz()));if(!telemetry.returning())state=new SpaceTrajectory("hud",0,state,telemetry.mu()).afterSeconds(SpaceHud.age(event.getPartialTick().getGameTimeDeltaPartialTick(false)));if(sensor!=null){statsFrames++;rows.add(new Row(Component.translatable("around_planet.helmet.orbit_speed",String.format(Locale.ROOT,"%.2f",state.velocity().length())),0xff9ee9df));rows.add(new Row(Component.translatable("around_planet.helmet.altitude",String.format(Locale.ROOT,"%.0f",state.position().length()-telemetry.radius())),0xffc5e2f0));}}
        if(sensor!=null&&telemetry!=null&&!telemetry.active()&&telemetry.radius()>0){statsFrames++;rows.add(new Row(Component.translatable("around_planet.helmet.surface_speed",String.format(Locale.ROOT,"%.2f",sensor.surfaceSpeed())),0xff9ee9df));rows.add(new Row(Component.translatable("around_planet.helmet.altitude",String.format(Locale.ROOT,"%.0f",sensor.surfaceAltitude())),0xffc5e2f0));}
        if(RendezvousClient.active()&&state!=null){double distance=RendezvousClient.other().position().subtract(RendezvousClient.own().position()).length(),speed=RendezvousClient.other().velocity().subtract(RendezvousClient.own().velocity()).length();rows.add(new Row(Component.translatable("around_planet.rendezvous.distance",String.format(Locale.ROOT,"%.1f",distance)),0xff70f5f1));rows.add(new Row(Component.translatable("around_planet.rendezvous.speed",String.format(Locale.ROOT,"%.2f",speed)),0xff70f5f1));}
        var g=event.getGuiGraphics();var layout=NavballLayout.of(g.guiWidth(),g.guiHeight(),AeroHelmetBridge.scale(linked.helmet()),AeroHelmetBridge.offset(linked.helmet(),true),AeroHelmetBridge.offset(linked.helmet(),false),rows.size());lastLayout=layout;
        if(sensor!=null){long start=io.github.astelev.around_planet.diagnostics.SeamDiagnostics.start();draw(g,sensor,OrbitalSensorVisual.read(sensor,event.getPartialTick().getGameTimeDeltaPartialTick(false)),layout,state,event.getPartialTick().getGameTimeDeltaPartialTick(false));frames++;io.github.astelev.around_planet.diagnostics.SeamDiagnostics.time("client","space.hud",start);}
        int right=sensor==null?g.guiWidth()-8:layout.textRight(),y=sensor==null?g.guiHeight()-16-(rows.size()-1)*11:layout.textTop();for(var row:rows){hudLine(g,row.text(),right,y,row.color());y+=11;}
    }
    private static void hudLine(GuiGraphics g,Component text,int right,int y,int color){var font=Minecraft.getInstance().font;int left=right-font.width(text);g.fill(left-3,y-1,right+3,y+10,0x9908121d);g.drawString(font,text,left,y,color,true);}
    private static SpaceVector instrument(OrbitalSensorBlockEntity sensor,SpaceVector world,float partial){return io.github.astelev.around_planet.sensor.OrbitalSensorBlock.frame(sensor.getBlockState()).instrument(io.github.astelev.around_planet.compat.SableSensorVisual.local(sensor,world,partial));}
    private static void update(SpaceVector up){var mc=Minecraft.getInstance();if(level!=mc.level){if(id!=null)mc.getTextureManager().release(id);texture=null;id=null;cachedUp=null;uploadTick=Long.MIN_VALUE;level=mc.level;}
        if(texture==null){texture=new DynamicTexture(new NativeImage(160,160,true));id=mc.getTextureManager().register("around_planet_orbital_navball",texture);}
        if(cachedUp!=null && uploadTick==mc.level.getGameTime())return;
        var quantized=new SpaceVector(Math.rint(up.x()*256)/256,Math.rint(up.y()*256)/256,Math.rint(up.z()*256)/256);if(quantized.equals(cachedUp))return;
        for(int y=0;y<160;y++)for(int x=0;x<160;x++){int c=NavballMath.color((x+.5-80)/79.5,-(y+.5-80)/79.5,quantized);texture.getPixels().setPixelRGBA(x,y,(c&0xFF00FF00)|((c>>>16)&255)|((c&255)<<16));}texture.upload();cachedUp=quantized;uploadTick=mc.level.getGameTime();textureUploads++;
    }
    private static void draw(GuiGraphics g,OrbitalSensorBlockEntity sensor,OrbitalSensorVisual.Reading reading,NavballLayout layout,SpaceState state,float partial){var mc=Minecraft.getInstance();int r=layout.radius(),x=layout.x(),y=layout.y();visibleTargetMarkers=0;cardinalLabels=0;var telemetry=SpaceHud.current();boolean space=state!=null&&telemetry!=null&&telemetry.active();var geographic=space?CardinalDirections.at(state.position()):SpaceFrame.IDENTITY;
        var upWorld=space?telemetry.frame().toLocal(geographic.up()):geographic.up();var northWorld=space?telemetry.frame().toLocal(geographic.south().scale(-1)):geographic.south().scale(-1);var eastWorld=space?telemetry.frame().toLocal(geographic.east()):geographic.east();var ballUp=instrument(sensor,upWorld,partial);var north=instrument(sensor,northWorld,partial);var east=instrument(sensor,eastWorld,partial);
        update(ballUp);g.flush();com.mojang.blaze3d.systems.RenderSystem.enableBlend();com.mojang.blaze3d.systems.RenderSystem.defaultBlendFunc();g.blit(id,x-r,y-r,2*r,2*r,0,0,160,160,160,160);com.mojang.blaze3d.systems.RenderSystem.disableBlend();var canvas=new Canvas(g.bufferSource().getBuffer(net.minecraft.client.renderer.RenderType.gui()),g.pose().last().pose());var labels=new ArrayList<Label>();compass(canvas,x,y,r,ballUp,north,east,labels);circle(canvas,x,y,r,0xff86b9c4);canvas.fill(x-10,y,x-2,y+1,0xffffdd60);canvas.fill(x+3,y,x+11,y+1,0xffffdd60);canvas.fill(x,y-2,x+1,y+3,0xffffdd60);
        boolean rear=false;if(sensor.active()&&!RendezvousMath.targetMode(sensor.mode())){var t=reading.target();boolean behind=t.z()<0;double px=t.x(),py=t.y();if(behind){double length=Math.hypot(px,py);if(length<1e-6){px=0;py=-1;}else{px/=length;py/=length;}}glyph(canvas,x+(int)Math.round(px*(r-5)),y-(int)Math.round(py*(r-5)),sensor.mode(),behind?0xffffa94f:0xff8dff66);rear=behind;}
        double distance=RendezvousClient.active()?RendezvousClient.other().position().subtract(RendezvousClient.own().position()).length():Double.POSITIVE_INFINITY;
        if(space&&NavballLayout.targetMarkers(RendezvousClient.active(),RendezvousClient.active()?RendezvousClient.current().target():null,distance))for(var mode:new OrbitalAttitude.Mode[]{OrbitalAttitude.Mode.TARGET,OrbitalAttitude.Mode.ANTI_TARGET,OrbitalAttitude.Mode.RELATIVE_PROGRADE,OrbitalAttitude.Mode.RELATIVE_RETROGRADE}){var direction=RendezvousClient.direction(mode);if(direction.isEmpty())continue;var t=instrument(sensor,telemetry.frame().toLocal(direction.get()),partial);double px=t.x(),py=t.y();boolean back=t.z()<0;if(back){double length=Math.hypot(px,py);if(length<1e-8){px=0;py=-1;}else{px/=length;py/=length;}}int mx=x+(int)Math.round(px*(r-6)),my=y-(int)Math.round(py*(r-6));int color=sensor.mode()==mode?0xffffffff:mode==OrbitalAttitude.Mode.TARGET||mode==OrbitalAttitude.Mode.ANTI_TARGET?0xff70f5f1:0xffff8edd;glyph(canvas,mx,my,mode,color);targetMarkers++;visibleTargetMarkers++;String name=switch(mode){case TARGET->"T+";case ANTI_TARGET->"T−";case RELATIVE_PROGRADE->"V+";default->"V−";};labels.add(new Label(mx+6,my-3,(back?"‹":"")+name,color,sensor.mode()==mode?3:2));}
        g.flush();geometryBatches++;drawLabels(g,labels,x,y,r);if(rear)g.drawCenteredString(mc.font,Component.translatable("around_planet.sensor.behind"),x,y-r-23,0xffffa94f);var label=!space?Component.translatable("around_planet.helmet.surface_horizon"):sensor.active()?OrbitalSensorScreen.name(sensor.mode()):Component.translatable("around_planet.sensor.hud_inactive");int half=mc.font.width(label)/2;g.drawCenteredString(mc.font,label,Math.clamp(x,half+4,g.guiWidth()-half-4),y-r-12,sensor.active()?0xff99ff88:0xffb8d9e0);
    }
    private static void compass(Canvas canvas,int x,int y,int r,SpaceVector up,SpaceVector north,SpaceVector east,List<Label> labels){SpaceVector[] directions={north,east,north.scale(-1),east.scale(-1)};String[] names={"north","east","south","west"};int[] colors={0xffc4e8ff,0xfff1d795,0xffa8d6c1,0xffd9c6ed};for(int i=0;i<4;i++){SpaceVector previous=null;for(int pitch=-80;pitch<=80;pitch+=5){double angle=Math.toRadians(pitch);var point=directions[i].scale(Math.cos(angle)).add(up.scale(Math.sin(angle)));if(previous!=null&&previous.z()>=0&&point.z()>=0)line(canvas,x+(int)Math.round(previous.x()*(r-3)),y-(int)Math.round(previous.y()*(r-3)),x+(int)Math.round(point.x()*(r-3)),y-(int)Math.round(point.y()*(r-3)),colors[i]&0xffbfbfbf);previous=point;}double angle=Math.toRadians(up.z()>=0?13:-13);var mark=directions[i].scale(Math.cos(angle)).add(up.scale(Math.sin(angle)));if(mark.z()>=-1e-6){String text=Component.translatable("around_planet.helmet.cardinal."+names[i]).getString();labels.add(new Label(x+(int)Math.round(mark.x()*(r-6))-Minecraft.getInstance().font.width(text)/2,y-(int)Math.round(mark.y()*(r-6))-4,text,colors[i],1));cardinalLabels++;}}}
    private static void drawLabels(GuiGraphics g,List<Label> labels,int x,int y,int r){var font=Minecraft.getInstance().font;var boxes=new ArrayList<int[]>();labels.sort(Comparator.comparingInt(Label::priority).reversed());for(var label:labels){int w=font.width(label.text()),lx=Math.clamp(label.x(),x-r+3,x+r-w-3),ly=Math.clamp(label.y(),y-r+3,y+r-12);for(int attempt=0;attempt<9;attempt++){boolean overlap=false;for(var box:boxes)if(lx<box[0]+box[2]+2&&lx+w+2>box[0]&&ly<box[1]+10&&ly+10>box[1]){overlap=true;break;}if(!overlap)break;ly=Math.clamp(label.y()+(attempt%2==0?1:-1)*((attempt/2)+1)*10,y-r+3,y+r-12);}boxes.add(new int[]{lx,ly,w});g.drawString(font,label.text(),lx,ly,label.color(),true);}}
    private static void glyph(Canvas g,int x,int y,OrbitalAttitude.Mode mode,int color){switch(mode){case NORMAL,ANTINORMAL->{line(g,x,y-5,x-5,y+4,color);line(g,x-5,y+4,x+5,y+4,color);line(g,x+5,y+4,x,y-5,color);}case RADIAL_OUT,RADIAL_IN,PLANET_OUT,PLANET_IN,TARGET,ANTI_TARGET->{line(g,x,y-5,x+5,y,color);line(g,x+5,y,x,y+5,color);line(g,x,y+5,x-5,y,color);line(g,x-5,y,x,y-5,color);}default->circle(g,x,y,5,color);}
        if(mode==OrbitalAttitude.Mode.RETROGRADE || mode==OrbitalAttitude.Mode.ANTINORMAL || mode==OrbitalAttitude.Mode.RADIAL_IN || mode==OrbitalAttitude.Mode.PLANET_IN||mode==OrbitalAttitude.Mode.ANTI_TARGET||mode==OrbitalAttitude.Mode.RELATIVE_RETROGRADE){line(g,x-3,y-3,x+3,y+3,color);line(g,x-3,y+3,x+3,y-3,color);}else{g.fill(x-8,y,x-4,y+1,color);g.fill(x+5,y,x+9,y+1,color);g.fill(x,y-8,x+1,y-4,color);}}
    private static void circle(Canvas g,int x,int y,int r,int color){for(int i=0;i<64;i++){double a=i*2*Math.PI/64,b=(i+1)*2*Math.PI/64;line(g,x+(int)Math.round(r*Math.cos(a)),y+(int)Math.round(r*Math.sin(a)),x+(int)Math.round(r*Math.cos(b)),y+(int)Math.round(r*Math.sin(b)),color);}}
    private static void line(Canvas g,int a,int b,int c,int d,int color){int n=Math.max(Math.abs(c-a),Math.abs(d-b));for(int i=0;i<=n;i++){int x=n==0?a:a+(c-a)*i/n,y=n==0?b:b+(d-b)*i/n;g.fill(x,y,x+1,y+1,color);}}
    private record Canvas(com.mojang.blaze3d.vertex.VertexConsumer vertices,org.joml.Matrix4f matrix){
        void fill(int a,int b,int c,int d,int color){vertices.addVertex(matrix,a,b,0).setColor(color);vertices.addVertex(matrix,a,d,0).setColor(color);vertices.addVertex(matrix,c,d,0).setColor(color);vertices.addVertex(matrix,c,b,0).setColor(color);}
    }
    private OrbitalHelmetHud(){}
}
